package com.pointverse.app;

import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.io.*;
import java.nio.file.Files;
import java.util.*;

/** Verify every attachment first; commit a whole point atomically, preserving concurrent local edits. */
final class CloudRestore {
    static final class Result {final String id,kind;Result(String id,String kind){this.id=id;this.kind=kind;}}
    static String uuid(String value)throws IOException {try{String id=UUID.fromString(value).toString();if(!id.equalsIgnoreCase(value))throw new IllegalArgumentException();return id;}catch(Exception e){throw new IOException("云端记录标识无效");}}
    static String hash(String value)throws IOException {if(!value.matches("[a-f0-9]{64}"))throw new IOException("云端文件标识无效");return value;}
    static JSONObject source(PointStore store,String id){try(Cursor c=store.getReadableDatabase().rawQuery("SELECT manifest,files,primary_audio,primary_message FROM sync_sources WHERE point_id=?",new String[]{id})){if(c.moveToFirst())return new JSONObject().put("manifest",new JSONObject(c.getString(0))).put("files",new JSONObject(c.getString(1))).put("primary_audio",c.getString(2)).put("primary_message",c.getString(3));}catch(JSONException e){throw new IllegalStateException(e);}return new JSONObject();}
    static boolean seen(PointStore store,String account,String remote,String hash){try(Cursor c=store.getReadableDatabase().rawQuery("SELECT 1 FROM sync_versions WHERE account=? AND remote_id=? AND manifest_hash=?",new String[]{account,remote,hash})){return c.moveToFirst();}}
    static void mark(PointStore store,String account,String remote,String hash,String local,int revision){ContentValues v=new ContentValues();v.put("account",account);v.put("remote_id",remote);v.put("manifest_hash",hash);v.put("local_id",local);v.put("local_revision",revision);store.getWritableDatabase().insertWithOnConflict("sync_versions",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
    static void validate(JSONObject m)throws Exception {
        String id=uuid(m.getString("point_id"));if(m.getInt("format_version")!=1||m.getInt("revision")<1||m.getDouble("created_at")<=0)throw new IOException("云端版本格式不支持");JSONArray points=m.getJSONObject("payload").getJSONArray("points");if(points.length()!=1||!uuid(points.getJSONObject(0).getString("id")).equals(id)||points.getJSONObject(0).getInt("head_revision")!=m.getInt("revision"))throw new IOException("云端版本内容不完整");JSONArray assets=m.getJSONArray("assets");if(assets.length()>128)throw new IOException("云端附件数量超限");Set<String> ids=new HashSet<>();for(int i=0;i<assets.length();i++){JSONObject a=assets.getJSONObject(i);if(!ids.add(uuid(a.getString("id")))||!Arrays.asList("audio","image").contains(a.getString("kind"))||a.getLong("byte_count")<=0||a.getLong("byte_count")>128L*1024*1024)throw new IOException("云端附件清单异常");hash(a.getString("sha256"));}
    }
    private static JSONArray array(JSONObject o,String key){JSONArray a=o.optJSONArray(key);return a==null?new JSONArray():a;}
    private static long milliseconds(JSONObject row,String key,long fallback){if(!row.has(key)||row.isNull(key))return fallback;double t=row.optDouble(key,0);return t>0?(long)(t*1000):fallback;}
    private static void copy(File from,File to)throws Exception {File temp=new File(to.getParentFile(),UUID.randomUUID()+".incoming");try{try(InputStream in=new FileInputStream(from);FileOutputStream out=new FileOutputStream(temp)){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("下载已暂停");out.write(b,0,n);}out.getFD().sync();}android.system.Os.rename(temp.getAbsolutePath(),to.getAbsolutePath());}finally{temp.delete();}}
    private static Object remap(Object value,Map<String,String> ids)throws Exception {if(value instanceof JSONObject){JSONObject source=(JSONObject)value,result=new JSONObject();for(Iterator<String> it=source.keys();it.hasNext();){String key=it.next();Object v=source.get(key);if(v instanceof String&&(key.equals("id")||key.endsWith("_id"))){String old=((String)v).toLowerCase(Locale.ROOT);v=ids.getOrDefault(old,(String)v);}result.put(key,remap(v,ids));}return result;}if(value instanceof JSONArray){JSONArray result=new JSONArray(),a=(JSONArray)value;for(int i=0;i<a.length();i++)result.put(remap(a.get(i),ids));return result;}return value;}
    static Result install(PointStore store,String account,String manifestHash,JSONObject original,Map<String,File> downloads)throws Exception {return install(store,account,manifestHash,original,downloads,false);}
    static Result install(PointStore store,String account,String manifestHash,JSONObject original,Map<String,File> downloads,boolean asCopy)throws Exception {
        validate(original);String remote=uuid(original.getString("point_id"));hash(manifestHash);if(!asCopy&&seen(store,account,remote,manifestHash))return new Result(remote,"skipped");
        JSONArray descriptors=original.getJSONArray("assets");for(int i=0;i<descriptors.length();i++){JSONObject a=descriptors.getJSONObject(i);File file=downloads.get(a.getString("sha256"));if(file==null||file.length()!=a.getLong("byte_count")||!LocalSpeech.hash(file).equals(a.getString("sha256")))throw new IOException("附件缺失或校验失败，本机内容未改变");}
        SQLiteDatabase db=store.getWritableDatabase();List<File> created=new ArrayList<>(),obsolete=new ArrayList<>();Set<String> retained=new HashSet<>();boolean committed=false;db.beginTransaction();
        try{
            if(!asCopy&&seen(store,account,remote,manifestHash)){db.setTransactionSuccessful();return new Result(remote,"skipped");}
            try(Cursor tomb=db.rawQuery("SELECT 1 FROM tombstones WHERE id=?",new String[]{remote})){if(!asCopy&&tomb.moveToFirst()){db.setTransactionSuccessful();return new Result(remote,"deleted");}}
            PointStore.Point current=null;try{current=store.get(remote);}catch(IllegalStateException absent){}
            if(!asCopy&&current!=null&&current.trashed!=0){db.setTransactionSuccessful();return new Result(remote,"deleted");}
            boolean replace=false;if(!asCopy&&current!=null)try(Cursor base=db.rawQuery("SELECT local_revision FROM sync_versions WHERE account=? AND remote_id=? AND local_id=? ORDER BY rowid DESC LIMIT 1",new String[]{account,remote,remote})){replace=base.moveToFirst()&&base.getInt(0)==current.revision;}
            if(replace){if(current.path!=null)obsolete.add(store.audioFile(current));JSONArray oldImages=store.rows("images",remote);for(int i=0;i<oldImages.length();i++)obsolete.add(new File(store.imageDirectory(),oldImages.getJSONObject(i).getString("path")));JSONObject oldFiles=source(store,remote).optJSONObject("files");if(oldFiles!=null)for(Iterator<String> it=oldFiles.keys();it.hasNext();)obsolete.add(new File(store.audio.getParentFile(),oldFiles.getString(it.next())));}
            boolean conflict=asCopy||current!=null&&!replace;String local=conflict?UUID.randomUUID().toString():remote;int revision=current==null?original.getInt("revision"):conflict?1:Math.max(current.revision,original.getInt("revision"))+1;
            Map<String,String> ids=new HashMap<>();ids.put(remote,local);JSONObject payload=original.getJSONObject("payload");
            for(Iterator<String> keys=payload.keys();keys.hasNext();){Object object=payload.opt(keys.next());if(!(object instanceof JSONArray))continue;JSONArray rows=(JSONArray)object;for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null||!row.has("id"))continue;String old=row.optString("id");try{String normalized=uuid(old);if(!normalized.equals(remote))ids.put(normalized,conflict?UUID.randomUUID().toString():normalized);}catch(IOException ignored){}}}
            for(int i=0;i<descriptors.length();i++){String id=uuid(descriptors.getJSONObject(i).getString("id"));ids.putIfAbsent(id,conflict?UUID.randomUUID().toString():id);}
            // Child IDs are global in the native store. Never steal another point's row.
            String[][] tables={{"point_images","images"},{"messages","conversation"},{"transcription_candidates","candidates"},{"manifestations","manifestations"}};
            for(String[] table:tables)for(int i=0;i<array(payload,table[0]).length();i++){JSONObject row=array(payload,table[0]).optJSONObject(i);if(row==null)continue;String old=row.optString("id").toLowerCase(Locale.ROOT),mapped=ids.get(old);if(mapped==null)continue;try(Cursor c=db.rawQuery("SELECT point_id FROM "+table[1]+" WHERE id=?",new String[]{mapped})){if(c.moveToFirst()&&!c.getString(0).equals(local))ids.put(old,UUID.randomUUID().toString());}}
            JSONObject manifest=(JSONObject)remap(original,ids);manifest.put("point_id",local);JSONObject data=manifest.getJSONObject("payload");JSONObject point=data.getJSONArray("points").getJSONObject(0);point.put("id",local).put("head_revision",revision);manifest.put("revision",revision);
            JSONObject files=new JSONObject();File folder=new File(store.cloudDirectory(),local);if(!folder.exists()&&!folder.mkdirs())throw new IOException("无法保存下载附件");
            for(int i=0;i<manifest.getJSONArray("assets").length();i++){JSONObject a=manifest.getJSONArray("assets").getJSONObject(i);File destination=new File(folder,a.getString("sha256")+".bin");if(!destination.isFile()||destination.length()!=a.getLong("byte_count")||!LocalSpeech.hash(destination).equals(a.getString("sha256"))){copy(downloads.get(a.getString("sha256")),destination);created.add(destination);}retained.add(destination.getAbsolutePath());files.put(uuid(a.getString("id")),"cloud/"+local+"/"+destination.getName());}
            JSONArray messages=array(data,"messages");List<JSONObject> ordered=new ArrayList<>();for(int i=0;i<messages.length();i++)ordered.add(messages.getJSONObject(i));ordered.sort(Comparator.comparingInt(m->m.optInt("sequence")));JSONObject first=ordered.isEmpty()?new JSONObject():ordered.get(0);String messageID=first.optString("id"),primaryAudio="";JSONObject primary=new JSONObject();JSONArray audio=array(data,"audio_assets");for(int i=0;i<audio.length();i++){JSONObject row=audio.getJSONObject(i);if(primaryAudio.isEmpty()||row.optString("message_id").equals(messageID)){primary=row;primaryAudio=uuid(row.getString("id"));if(row.optString("message_id").equals(messageID))break;}}
            if(primaryAudio.isEmpty())for(int i=0;i<manifest.getJSONArray("assets").length();i++){JSONObject a=manifest.getJSONArray("assets").getJSONObject(i);if(a.getString("kind").equals("audio")){primaryAudio=uuid(a.getString("id"));primary=a;break;}}
            JSONObject transcript=new JSONObject();JSONArray transcripts=array(data,"transcripts");for(int i=0;i<transcripts.length();i++)if(transcripts.getJSONObject(i).optString("asset_id").equals(primaryAudio)){transcript=transcripts.getJSONObject(i);break;}
            String body=first.optString("user_text","");String machine=transcript.optString("engine_text","");int edited=0;if(!transcript.isNull("user_text")&&transcript.has("user_text")){body=transcript.optString("user_text");edited=1;}
            JSONObject nativePoint=data.optJSONObject("android_point");if(nativePoint!=null){body=nativePoint.optString("body",body);machine=nativePoint.optString("machine",machine);edited=nativePoint.optInt("edited",edited);}
            ContentValues values=new ContentValues();values.put("id",local);values.put("title",(conflict?"云端副本 · ":"")+manifest.optString("title",point.optString("accepted_title","未命名想法")));values.put("body",body);values.put("machine",machine);values.put("edited",edited);values.put("created",(long)(manifest.getDouble("created_at")*1000));values.put("revision",revision);values.put("title_edited",1);values.put("embedding","");
            if(!primaryAudio.isEmpty()){if(!files.has(primaryAudio))throw new IOException("原音附件缺失");values.put("audio_path",files.getString(primaryAudio));values.put("duration",primary.optLong("duration_ms",0));values.put("sha256",primary.optString("sha256"));}else values.putNull("audio_path");
            for(String field:new String[]{"summary","speaker","voice","domain","topic","project","expression","manual","locale","analysis","title_source","title_model"})if(nativePoint!=null&&nativePoint.has(field))values.put(field,nativePoint.optString(field));if(nativePoint!=null){values.put("title_edited",conflict?1:nativePoint.optInt("title_edited",1));values.put("title_version",nativePoint.optInt("title_version",0));}
            JSONArray derivations=array(data,"derivations");if(nativePoint==null&&derivations.length()>0)values.put("summary",derivations.getJSONObject(derivations.length()-1).optString("summary"));
            JSONArray facets=array(data,"facet_overrides");if(nativePoint==null&&facets.length()>0){List<String> manual=new ArrayList<>();for(int i=0;i<facets.length();i++){JSONObject f=facets.getJSONObject(i);String dimension=f.optString("dimension");if(Arrays.asList("domain","topic","project","expression").contains(dimension)){JSONArray v=new JSONArray(f.optString("values_json","[]"));values.put(dimension,v.length()==0?"":v.optString(0));manual.add(dimension);}}values.put("manual",String.join(",",manual));}
            if(replace){db.update("points",values,"id=?",new String[]{local});for(String table:new String[]{"images","conversation","candidates","manifestations","snapshots"})db.delete(table,"point_id=?",new String[]{local});}else db.insertOrThrow("points",null,values);
            JSONArray images=array(data,"point_images");for(int i=0;i<images.length();i++){JSONObject row=images.getJSONObject(i);String imageID=uuid(row.getString("id"));if(!files.has(imageID))throw new IOException("图片附件缺失");File from=new File(store.audio.getParentFile(),files.getString(imageID)),to=new File(store.imageDirectory(),UUID.randomUUID()+".image");copy(from,to);created.add(to);retained.add(to.getAbsolutePath());ContentValues v=new ContentValues();v.put("id",imageID);v.put("point_id",local);v.put("path",to.getName());v.put("caption",row.optString("caption",row.optString("recognized_text","")));v.put("model",row.optString("model",row.optString("model_id","")));v.put("created",row.optLong("created",milliseconds(row,"created_at",System.currentTimeMillis())));for(String field:new String[]{"ocr_text","visual_text","visual_model","ocr_model","analysis_error"})v.put(field,row.optString(field));v.put("analysis_state",row.optString("analysis_state","complete"));v.put("caption_edited",row.optInt("caption_edited",1));v.put("ocr_done",row.optInt("ocr_done",1));db.insertOrThrow("images",null,v);}
            for(int i=1;i<ordered.size();i++){JSONObject row=ordered.get(i);String text=row.optString("user_text",row.optString("text",""));if(text.isEmpty())continue;ContentValues v=new ContentValues();v.put("id",uuid(row.getString("id")));v.put("point_id",local);v.put("role",row.optString("role","user"));v.put("text",text);v.put("model",row.optString("model_id",""));v.put("created",milliseconds(row,"created_at",System.currentTimeMillis()+i));db.insertOrThrow("conversation",null,v);}
            JSONArray candidates=array(data,"transcription_candidates");for(int i=0;i<candidates.length();i++){JSONObject row=candidates.getJSONObject(i);ContentValues v=new ContentValues();v.put("id",row.has("id")?uuid(row.getString("id")):UUID.randomUUID().toString());v.put("point_id",local);v.put("engine",row.optString("engine",row.optString("model_id","cloud")));v.put("text",row.optString("text",row.optString("engine_text","")));v.put("created",row.optLong("created",milliseconds(row,"created_at",System.currentTimeMillis())));db.insertOrThrow("candidates",null,v);}
            JSONArray works=array(data,"manifestations");for(int i=0;i<works.length();i++){JSONObject row=works.getJSONObject(i);String content=row.optString("content");if(row.optString("kind").equals("image"))content=ids.getOrDefault(content.toLowerCase(Locale.ROOT),content);ContentValues v=new ContentValues();v.put("id",uuid(row.getString("id")));v.put("point_id",local);v.put("kind",row.optString("kind","text"));v.put("content",content);v.put("model",row.optString("model"));v.put("lens",row.optString("lens","original"));v.put("source_revision",row.optInt("source_revision",revision));v.put("created",row.optLong("created",System.currentTimeMillis()));db.insertOrThrow("manifestations",null,v);}
            JSONArray relations=array(data,"android_relations");if(!data.has("android_relations"))relations=array(data,"confirmed_relations");for(int i=0;i<relations.length();i++){JSONObject row=relations.getJSONObject(i);String from=row.optString("source",row.optString("source_point_id")),to=row.optString("target",row.optString("target_point_id"));try{from=ids.getOrDefault(uuid(from),uuid(from));to=ids.getOrDefault(uuid(to),uuid(to));}catch(IOException invalid){continue;}if(!from.equals(local)&&!to.equals(local))continue;ContentValues v=new ContentValues();v.put("source",from);v.put("target",to);v.put("type",row.optString("type",row.optString("relation_type","相关")));db.insertWithOnConflict("relations",null,v,SQLiteDatabase.CONFLICT_IGNORE);}
            ContentValues origin=new ContentValues();origin.put("point_id",local);origin.put("manifest",manifest.toString());origin.put("files",files.toString());origin.put("primary_audio",primaryAudio);origin.put("primary_message",messageID);db.insertWithOnConflict("sync_sources",null,origin,SQLiteDatabase.CONFLICT_REPLACE);if(!conflict||!seen(store,account,remote,manifestHash))mark(store,account,remote,manifestHash,local,revision);db.setTransactionSuccessful();committed=true;return new Result(local,conflict?"conflict":replace?"updated":"added");
        }finally{db.endTransaction();if(!committed)for(File file:created)file.delete();else for(File file:obsolete)if(!retained.contains(file.getAbsolutePath()))file.delete();}
    }
}
